function make(n) {
    let v = n;
    return function() {
        return v;
    };
}

const a = make(10);
const b = make(20);
// a() is 10 and b() is 20 — each function keeps its own closed-over binding
a();
b();

// ECMAScript
let x = 1 // invalid in Adaptive Script (missing ;)
let y = 2;
'abc' // invalid in Adaptive Script (expression as statement)

try {
    throw "Something bad happened" data { "code": 123 };
} catch (e) {
    print(e.message);
    print(e.data.code);
}

try {
    throw "Person not found" id "not_found" data { personId: id };
} catch (e) {
    if (e.id === "not_found") {
        print(e.data.personId);
    } else {
        throw;
    }
}

try {
    throw "boom";
} catch ({ message }) {
    print(message);
}

let y = "c";
let x = {
    a:   1,
    "b": 2,
    [y]: 3,
    ["Customer Name"]: "Ada"
};
assert(x.c === 3);
assert(x["Customer Name"] === "Ada");

let names = keys(x);
let a = [1, 2];
push(a, 3);
assert(at(a, -1) === 3);

/* Turn type checking on for this script */
#compile typeCheck;

const n: integer = 1;

/* Turn type checking off again in this script */
#compile noTypeCheck;
